"""Checks on the bundled kinematics/ (generated by scripts/extract_kinematics.py)."""

import asyncio
import xml.etree.ElementTree as ET
from pathlib import Path

import dexmate_urdf
import numpy as np
import pytest
from dexbot_utils.configs import get_robot_config
from viam.proto.app.robot import ComponentConfig
from viam.proto.common import KinematicsFileFormat
from viam.utils import dict_to_struct

from models.arm import KINEMATICS_DIR, Arm
from scripts import extract_kinematics as ek

PKG = Path(dexmate_urdf.__file__).parent / "robots"
URDFS = sorted(KINEMATICS_DIR.glob("*/*.urdf"))


def test_bundled_kinematics_match_installed_dexmate_urdf(tmp_path):
    """Fails when dexmate-urdf is bumped without rerunning the extractor."""
    for urdf, spheres in ek.variants(PKG):
        ek.extract(urdf, spheres, tmp_path / urdf.stem)
    fresh = sorted(p.relative_to(tmp_path) for p in tmp_path.rglob("*.*"))
    assert fresh == sorted(p.relative_to(KINEMATICS_DIR) for p in KINEMATICS_DIR.rglob("*.*"))
    for rel in fresh:
        assert (tmp_path / rel).read_text() == (KINEMATICS_DIR / rel).read_text(), f"{rel} is stale"


@pytest.mark.parametrize("urdf", URDFS, ids=lambda p: f"{p.parent.name}/{p.stem}")
def test_joint_order_matches_dexcontrol(urdf):
    """Viam joint i must be dexcontrol joint i, or every move goes to the wrong joint."""
    cfg = get_robot_config(urdf.parent.name.removesuffix("_no_ft"))
    movable = [j.get("name") for j in ET.parse(urdf).getroot().findall("joint") if j.get("type") != "fixed"]
    assert movable == list(cfg.components[urdf.stem].joints)


@pytest.mark.parametrize("urdf", URDFS, ids=lambda p: f"{p.parent.name}/{p.stem}")
def test_collision_boxes_contain_dexmate_spheres(urdf):
    sphere_urdf = next(s for u, s in ek.variants(PKG) if u.stem == urdf.parent.name)
    spheres = ek.Robot(sphere_urdf)
    for name, link in ek.Robot(urdf).links.items():
        col = link.find("collision")
        if col is None:
            continue
        to_box = np.linalg.inv(ek.origin_tf(col))
        for s in spheres.links[name].findall("collision"):
            c = (to_box @ ek.origin_tf(s)[:, 3])[:3]
            r = float(s.find("geometry/sphere").get("radius"))
            box = col.find("geometry/box")
            if box is not None:
                assert np.all(np.abs(c) + r <= ek._floats(box.get("size")) / 2 + 2e-6), name
            else:
                assert np.linalg.norm(c) + r <= float(col.find("geometry/sphere").get("radius")) + 2e-6, name


def make_arm(**attrs):
    cfg = ComponentConfig(name="a", attributes=dict_to_struct(attrs))
    Arm.validate_config(cfg)
    return Arm.new(cfg, {})


def test_variant_selects_bundled_urdf():
    fmt, data = asyncio.run(make_arm(component="left_arm", variant="vega_1p").get_kinematics())
    assert fmt == KinematicsFileFormat.KINEMATICS_FILE_FORMAT_URDF
    assert b'name="vega_1p_left_arm"' in data


def test_variant_without_torso_rejected():
    with pytest.raises(ValueError, match="vega_1u"):
        make_arm(component="torso", variant="vega_1u")


@pytest.mark.parametrize("suffix,variant", [("1", "vega_1"), ("1p", "vega_1p"), ("1u", "vega_1u")])
def test_robot_name_suffix_selects_variant(monkeypatch, suffix, variant):
    monkeypatch.setenv("ROBOT_NAME", f"dm/vg0123456789-{suffix}")
    _, data = asyncio.run(make_arm(component="left_arm").get_kinematics())
    assert f'name="{variant}_left_arm"'.encode() in data


def test_explicit_variant_overrides_robot_name(monkeypatch):
    monkeypatch.setenv("ROBOT_NAME", "dm/vg0123456789-1u")
    _, data = asyncio.run(make_arm(component="left_arm", variant="vega_1p_no_ft").get_kinematics())
    assert b'name="vega_1p_no_ft_left_arm"' in data


@pytest.mark.parametrize("name", [None, "dm/vg0123456789-2x", "nodash"])
def test_unknown_or_missing_robot_name_has_no_kinematics(monkeypatch, name):
    monkeypatch.delenv("ROBOT_NAME", raising=False)
    if name:
        monkeypatch.setenv("ROBOT_NAME", name)
    with pytest.raises(ValueError, match="set `variant`"):
        asyncio.run(make_arm(component="left_arm").get_kinematics())


def test_robot_name_without_torso_rejected(monkeypatch):
    monkeypatch.setenv("ROBOT_NAME", "dm/vg0123456789-1u")
    with pytest.raises(ValueError, match="vega_1u"):
        make_arm(component="torso")
